const lead = $json;

const errors = [];

// Required fields
const requiredFields = [
  'name',
  'email',
  'phone',
  'budget',
  'location',
  'propertyType',
  'timeline'
];

for (const field of requiredFields) {
  if (
    lead[field] === undefined ||
    lead[field] === null ||
    lead[field] === ''
  ) {
    errors.push(`${field} is required`);
  }
}

// Budget
if (
  lead.budget !== undefined &&
  (typeof lead.budget !== 'number' ||
    Number.isNaN(lead.budget) ||
    lead.budget <= 0)
) {
  errors.push('Budget must be a valid positive number');
}

// Email
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (lead.email && !emailRegex.test(lead.email)) {
  errors.push('Invalid email address');
}

// Phone
const phoneRegex = /^\+?[1-9]\d{7,14}$/;

if (lead.phone && !phoneRegex.test(lead.phone)) {
  errors.push('Invalid phone number');
}

return [
  {
    json: {
      ...lead,

      validation: {
        valid: errors.length === 0,
        errors
      }
    }
  }
];

const lead = $('Normalize Lead').first().json;

const listings = $input.all();

const scoredListings = listings.map(item => {
  const property = item.json;

  let score = 0;

  // Normalize everything first
  const listingCity = String(property.address?.city || '')
    .trim()
    .toLowerCase();

  const requestedCity = String(lead.location || '')
    .trim()
    .toLowerCase();

  const listingPrice = Number(property.listPrice);

  const budget = Number(lead.budget);

  const listingType = String(property.property?.type || '')
    .trim()
    .toUpperCase();

  const requestedType = String(lead.propertyType || '')
    .trim()
    .toUpperCase();


  // -------------------------
  // LOCATION
  // -------------------------

  const locationMatched =
    listingCity === requestedCity;

  if (locationMatched) {
    score += 40;
  }


  // -------------------------
  // BUDGET
  // -------------------------

  const budgetMatched =
    Number.isFinite(listingPrice) &&
    Number.isFinite(budget) &&
    listingPrice <= budget;

  if (budgetMatched) {
    score += 30;
  }


  // -------------------------
  // PROPERTY TYPE
  // -------------------------

  const propertyTypeMatched =
    listingType === requestedType;

  if (propertyTypeMatched) {
    score += 20;
  }


  // -------------------------
  // WITHIN 10% OF BUDGET
  // -------------------------

  const nearBudgetMatched =
    Number.isFinite(listingPrice) &&
    Number.isFinite(budget) &&
    listingPrice >= budget * 0.9 &&
    listingPrice <= budget;

  if (nearBudgetMatched) {
    score += 10;
  }


  return {
    ...property,

    matchScore: score,

    // TEMPORARY DEBUG INFO
    debug: {
      requestedCity,
      listingCity,
      locationMatched,

      budget,
      listingPrice,
      budgetMatched,

      requestedType,
      listingType,
      propertyTypeMatched,

      minimumNearBudget: budget * 0.9,
      nearBudgetMatched
    }
  };
});


scoredListings.sort(
  (a, b) => b.matchScore - a.matchScore
);

const bestMatch = scoredListings[0] || null;

return [
  {
    json: {
      lead,

      totalListingsReceived: listings.length,

      listings: scoredListings.slice(0, 5),

      bestMatch,

      bestMatchScore: bestMatch?.matchScore ?? null,

      strongMatch: (bestMatch?.matchScore ?? 0) >= 80
    }
  }
];

