// Get the original lead data.
//
// We reference Normalize Lead directly because the two branches before this
// node don't have the same data shape:
//
// TRUE branch  → property/listing information
// FALSE branch → AI Agent output
//
// The normalized lead is the reliable source for scoring.
const lead = $('Normalize Lead').first().json;


// ------------------------------------------
// 1. BUDGET SCORE
// Maximum: 30 points
// ------------------------------------------

const budget = Number(lead.budget);

let budgetScore = 0;

if (budget >= 750000) {
  budgetScore = 30;
} else if (budget >= 500000) {
  budgetScore = 25;
} else if (budget >= 300000) {
  budgetScore = 20;
} else if (budget >= 150000) {
  budgetScore = 10;
} else {
  budgetScore = 5;
}


// ------------------------------------------
// 2. TIMELINE SCORE
// Maximum: 40 points
// ------------------------------------------

const timeline = String(lead.timeline || '')
  .trim()
  .toLowerCase();

let timelineScore = 0;

switch (timeline) {

  case 'immediately':
  case 'immediate':
    timelineScore = 40;
    break;

  case '0-3 months':
  case '0–3 months':
    timelineScore = 35;
    break;

  case '3-6 months':
  case '3–6 months':
    timelineScore = 25;
    break;

  case '6-12 months':
  case '6–12 months':
    timelineScore = 15;
    break;

  case 'just browsing':
  case 'browsing':
    timelineScore = 5;
    break;

  default:
    timelineScore = 5;
}


// ------------------------------------------
// 3. FINANCING SCORE
// Maximum: 30 points
// ------------------------------------------

let financingScore = 5;

if (
  lead.financingReady === true ||
  String(lead.financingReady).toLowerCase() === 'true'
) {
  financingScore = 30;
}


// ------------------------------------------
// 4. TOTAL SCORE
// ------------------------------------------

const totalScore =
  budgetScore +
  timelineScore +
  financingScore;


// ------------------------------------------
// 5. CLASSIFICATION
// ------------------------------------------

let leadTemperature;

if (totalScore >= 75) {

  leadTemperature = 'HOT';

} else if (totalScore >= 45) {

  leadTemperature = 'WARM';

} else {

  leadTemperature = 'COLD';

}


// ------------------------------------------
// 6. Get data from whichever branch reached
// this node
// ------------------------------------------

const currentInput = $input.first().json;


// ------------------------------------------
// 7. RETURN ONE CLEAN OBJECT
// ------------------------------------------

return [
  {
    json: {

      lead: {
        name: lead.name,
        email: lead.email,
        phone: lead.phone,
        budget: budget,
        location: lead.location,
        propertyType: lead.propertyType,
        timeline: lead.timeline,
        financingReady: lead.financingReady
      },

      scoring: {
        budgetScore: budgetScore,
        timelineScore: timelineScore,
        financingScore: financingScore,
        totalScore: totalScore,
        temperature: leadTemperature
      },

      enrichment: currentInput,

      scoredAt: new Date().toISOString()
    }
  }
];

